arguments.new_str:
namespace Payments;

public interface IPaymentProvider
{
    Task<string> CreateChargeAsync(string cardToken, decimal amount, CancellationToken cancellationToken = default);
    Task<string> CreateRefundAsync(string chargeId, CancellationToken cancellationToken = default);
}

public sealed class PaymentGateway
{
    private readonly IPaymentProvider _provider;
    private const decimal MinimumCharge = 0.50m;
    private const decimal MaximumCharge = 999_999.99m;

    public PaymentGateway(IPaymentProvider provider)
    {
        _provider = provider ?? throw new ArgumentNullException(nameof(provider));
    }

    public async Task<ChargeResult> ChargeAsync(string cardToken, decimal amount, CancellationToken cancellationToken = default)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(cardToken);

        if (amount < MinimumCharge)
            throw new ArgumentOutOfRangeException(nameof(amount), amount, $"Amount must be at least {MinimumCharge}.");
        if (amount > MaximumCharge)
            throw new ArgumentOutOfRangeException(nameof(amount), amount, $"Amount must not exceed {MaximumCharge}.");

        try
        {
            var chargeId = await _provider.CreateChargeAsync(cardToken, amount, cancellationToken);
            return new ChargeResult(chargeId, Success: true);
        }
        catch (OperationCanceledException)
        {
            throw;
        }
        catch (Exception ex)
        {
            return new ChargeResult(ChargeId: string.Empty, Success: false, ErrorMessage: ex.Message);
        }
    }

    public async Task<RefundResult> RefundAsync(string chargeId, CancellationToken cancellationToken = default)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(chargeId);

        try
        {
            var refundId = await _provider.CreateRefundAsync(chargeId, cancellationToken);
            return new RefundResult(refundId, Success: true);
        }
        catch (OperationCanceledException)
        {
            throw;
        }
        catch (Exception ex)
        {
            return new RefundResult(RefundId: string.Empty, Success: false, ErrorMessage: ex.Message);
        }
    }

    public WebhookResult ProcessWebhook(string eventType, string payload)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(eventType);
        ArgumentException.ThrowIfNullOrWhiteSpace(payload);

        return eventType switch
        {
            "charge.succeeded" => new WebhookResult(Handled: true, EventType: eventType),
            "charge.failed" => new WebhookResult(Handled: true, EventType: eventType),
            "refund.created" => new WebhookResult(Handled: true, EventType: eventType),
            _ => new WebhookResult(Handled: false, EventType: eventType),
        };
    }
}

public record ChargeResult(string ChargeId, bool Success, string? ErrorMessage = null);
public record RefundResult(string RefundId, bool Success, string? ErrorMessage = null);
public record WebhookResult(bool Handled, string EventType);

